/**
 * components/DynamicForm.jsx
 * Merender form dari daftar field_definitions — KOMPONEN INTI SISTEM
 * Tidak ada field yang ditulis manual — semua dari konfigurasi database
 */

import { useEffect, useLayoutEffect, useRef, useState } from 'react'
import { db, fieldFiles } from '../lib/db'
import { formatAngka, formatKetikan, isRupiahField, parseAngka } from '../lib/angka'
import { notify } from '../lib/dialog'
import { isTautan } from '../lib/tautan'
import { Link2, Lock, Paperclip } from 'lucide-react'

const FILE_ACCEPT = '.pdf,.doc,.docx,.xls,.xlsx'
const FILE_MAX_MB = 10

function formatFileSize(n) {
  const num = Number(n) || 0
  return num >= 1048576 ? `${(num / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(num / 1024))} KB`
}

/**
 * Ambil metadata berkas (nama, ukuran) untuk sebuah id field_files. Dipakai baik oleh kontrol unggah (FieldInput
 * tipe 'file') maupun tampilan baca-saja di tabel rekap (FileValueDisplay).
 */
function useFieldFileMeta(id) {
  const [meta, setMeta] = useState(null)
  const [loading, setLoading] = useState(!!id)
  useEffect(() => {
    let alive = true
    if (!id || isTautan(id)) { setMeta(null); setLoading(false); return } // link, bukan berkas unggahan
    setLoading(true)
    db.from('field_files').select('id,file_name,file_ext,file_size').eq('id', id).single()
      .then(({ data }) => { if (alive) { setMeta(data || null); setLoading(false) } })
      .catch(() => { if (alive) { setMeta(null); setLoading(false) } })
    return () => { alive = false }
  }, [id])
  return { meta, loading }
}

/** Tampilan baca-saja (tabel rekap): tombol unduh berkas, atau tautan bila isinya link data dukung. */
export function FileValueDisplay({ id, className = '' }) {
  const { meta, loading } = useFieldFileMeta(id)
  const [busy, setBusy] = useState(false)
  if (!id) return <span className="text-gray-300 dark:text-gray-600">—</span>
  if (isTautan(id)) {
    const url = id.trim()
    let host = url
    try { host = new URL(url).hostname.replace(/^www./, '') } catch { /* tetap tampilkan apa adanya */ }
    return (
      <a href={url} target="_blank" rel="noopener noreferrer" title={url}
        className={`inline-flex items-center gap-1 text-xs text-blue-600 dark:text-blue-400 hover:underline max-w-[16rem] truncate ${className}`}>
        <Link2 size={12} className="flex-shrink-0" /> Buka link ({host})
      </a>
    )
  }
  if (loading) return <span className="text-gray-400 text-xs">Memuat…</span>
  if (!meta) {
    // Bukan id berkas yang dikenal (mis. isian lama berupa teks/link sebelum kolom ini diganti tipe Berkas)
    return <span className="text-gray-500 dark:text-gray-400 text-xs break-all">{String(id)}</span>
  }
  return (
    <button
      type="button"
      disabled={busy}
      onClick={async () => { setBusy(true); try { await fieldFiles.download(id) } catch (e) { notify(e.message, 'error') } finally { setBusy(false) } }}
      className={`inline-flex items-center gap-1 text-xs text-blue-600 dark:text-blue-400 hover:underline disabled:opacity-50 ${className}`}
      title={`${meta.file_name} (${formatFileSize(meta.file_size)})`}
    >
      <Paperclip size={12} className="flex-shrink-0" /> {busy ? 'Mengunduh…' : meta.file_name}
    </button>
  )
}

/** Kontrol unggah untuk form input (FieldInput tipe 'file'). */
function FileFieldInput({ field, value, onChange, disabled, idPrefix, jenisDataId, uptKey }) {
  const { meta, loading } = useFieldFileMeta(value)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [link, setLink] = useState(isTautan(value) ? value : '')
  const berkasLama = v => (v && !isTautan(v) ? v : null) // id field_files yang perlu dibuang bila diganti

  // Link sah dipakai langsung saat diketik/ditempel; saat kursor keluar, isian yang bukan link sah diberi pesan.
  function simpanLink(isi = link) {
    const url = String(isi).trim()
    setError('')
    if (!url) return
    if (!isTautan(url)) { setError('Link harus diawali http:// atau https:// (mis. link folder Google Drive).'); return }
    const prevId = berkasLama(value)
    onChange(field.field_key, url)
    if (prevId) fieldFiles.remove(prevId).catch(() => {}) // ganti berkas dengan link: buang berkas lama
  }

  async function handleFile(e) {
    const file = e.target.files?.[0]
    e.target.value = '' // supaya memilih berkas yang sama lagi tetap memicu onChange
    if (!file) return
    setError('')
    if (file.size > FILE_MAX_MB * 1024 * 1024) { setError(`Ukuran berkas melebihi ${FILE_MAX_MB} MB.`); return }
    if (!jenisDataId || !uptKey) { setError('Pilih UPT terlebih dahulu sebelum mengunggah berkas.'); return }
    setBusy(true)
    const prevId = value
    const { data, error: err } = await fieldFiles.upload(file, { jenis_data_id: jenisDataId, field_key: field.field_key, upt_key: uptKey })
    setBusy(false)
    if (err) { setError(err.message); return }
    onChange(field.field_key, data.id)
    setLink('')
    if (berkasLama(prevId) && prevId !== data.id) fieldFiles.remove(prevId).catch(() => {}) // ganti berkas: buang yang lama
  }

  return (
    <div className="space-y-1.5">
      {value && (
        <div className="flex items-center gap-2 text-xs">
          {loading ? (
            <span className="text-gray-400">Memuat…</span>
          ) : isTautan(value) ? (
            <FileValueDisplay id={value} />
          ) : meta ? (
            <>
              <FileValueDisplay id={value} />
              <span className="text-gray-400">({formatFileSize(meta.file_size)})</span>
            </>
          ) : (
            <span className="text-gray-500 dark:text-gray-400 break-all">{String(value)}</span>
          )}
          {!disabled && (
            <button type="button" onClick={() => { onChange(field.field_key, null); setLink('') }} className="text-rose-500 hover:underline">Hapus</button>
          )}
        </div>
      )}
      {!disabled && (
        <input
          id={`${idPrefix}field-${field.field_key}`}
          type="file"
          accept={FILE_ACCEPT}
          onChange={handleFile}
          disabled={busy}
          className="block w-full text-xs text-gray-600 dark:text-gray-300 file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-medium file:bg-blue-50 file:text-blue-700 dark:file:bg-blue-950/40 dark:file:text-blue-300 hover:file:bg-blue-100"
        />
      )}
      {!disabled && (
        <div className="flex items-center gap-2">
          <span className="text-[11px] text-gray-400 flex-shrink-0">atau link:</span>
          <input
            type="url"
            value={link}
            onChange={e => { const v = e.target.value; setLink(v); setError(''); if (isTautan(v.trim()) && v.trim() !== value) simpanLink(v) }}
            onBlur={() => simpanLink()}
            onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); simpanLink() } }}
            placeholder="https://drive.google.com/..."
            className="form-input text-xs py-1.5"
            disabled={busy}
          />
        </div>
      )}
      {busy && <p className="text-xs text-blue-500">Mengunggah…</p>}
      {error && <p className="text-xs text-rose-500">{error}</p>}
      <p className="text-[10px] text-gray-400">Unggah PDF, Word, atau Excel (maks. {FILE_MAX_MB} MB), atau tempel link data dukung (mis. folder Google Drive).</p>
    </div>
  )
}

/**
 * Isian angka bergaya Indonesia: titik ribuan muncul otomatis saat mengetik (1.500.000), koma untuk desimal.
 * Nilai yang dikirim ke onChange tetap number (atau null bila kosong). Kolom rupiah diberi awalan "Rp".
 */
function AngkaInput({ id, value, onChange, className, disabled, required, rupiah }) {
  const [teks, setTeks] = useState(() => formatAngka(value))
  const ref = useRef(null)
  const caret = useRef(null) // banyaknya digit/koma di kiri kursor, untuk mengembalikan posisi kursor setelah diformat

  // Nilai diubah dari luar (form dibuka untuk baris lain, dikosongkan): tampilkan ulang
  useEffect(() => {
    const kini = value === '' || value === undefined || value === null ? null : Number(value)
    if (parseAngka(teks) !== kini) setTeks(formatAngka(value))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value])

  useLayoutEffect(() => {
    const el = ref.current
    if (caret.current === null || !el || document.activeElement !== el) return
    let pos = 0
    for (let n = 0; pos < el.value.length && n < caret.current; pos++) if (/[\d,]/.test(el.value[pos])) n++
    caret.current = null
    el.setSelectionRange(pos, pos)
  }, [teks])

  function ketik(e) {
    const raw = e.target.value
    caret.current = raw.slice(0, e.target.selectionStart ?? raw.length).replace(/[^\d,]/g, '').length
    const t = formatKetikan(raw)
    setTeks(t)
    onChange(parseAngka(t))
  }

  const input = (
    <input
      ref={ref}
      id={id}
      type="text"
      inputMode="decimal"
      autoComplete="off"
      value={teks}
      onChange={ketik}
      className={`${className} tabular-nums ${rupiah ? 'pl-10' : ''}`}
      disabled={disabled}
      required={required}
      placeholder="0"
    />
  )
  if (!rupiah) return input
  return (
    <div className="relative">
      <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-sm text-gray-400">Rp</span>
      {input}
    </div>
  )
}

export function FieldInput({ field, value, onChange, disabled, idPrefix = '', jenisDataId, uptKey, allValues, allFields }) {
  const base = `form-input ${disabled ? 'opacity-60 cursor-not-allowed bg-gray-50 dark:bg-gray-800' : ''}`

  switch (field.tipe) {
    case 'angka':
      return (
        <AngkaInput
          id={`${idPrefix}field-${field.field_key}`}
          value={value}
          onChange={v => onChange(field.field_key, v)}
          className={base}
          disabled={disabled}
          required={field.wajib}
          rupiah={isRupiahField(field)}
        />
      )

    case 'file':
      return (
        <FileFieldInput
          field={field}
          value={value}
          onChange={onChange}
          disabled={disabled}
          idPrefix={idPrefix}
          jenisDataId={jenisDataId}
          uptKey={uptKey}
        />
      )

    case 'tanggal': {
      // Kolom yang memang satu titik waktu (mis. "Dokumen Kontrak: Tanggal Mulai/Selesai", "Tanggal Awal/Akhir")
      // -> satu tanggal saja
      if (/tanggal (mulai|selesai|awal|akhir)/i.test(field.label || '') || /_(mulai|selesai|awal|akhir)(_|$)/.test(field.field_key)) {
        return (
          <input
            id={`${idPrefix}field-${field.field_key}`}
            type="date"
            value={value ? String(value).split(' s/d ')[0].split('T')[0] : ''}
            onChange={e => onChange(field.field_key, e.target.value || null)}
            className={base}
            disabled={disabled}
            required={field.wajib}
          />
        )
      }
      const isRange = typeof value === 'string' && value.includes(' s/d ')
      const parts = isRange ? value.split(' s/d ') : [value || '', '']
      const [startDate, endDate] = parts

      return (
        <div className="space-y-1.5">
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="text-[10px] text-gray-400 font-medium block mb-0.5">Dari Tanggal</label>
              <input
                id={`${idPrefix}field-${field.field_key}-start`}
                type="date"
                value={startDate ? String(startDate).split('T')[0] : ''}
                onChange={(e) => {
                  const newStart = e.target.value
                  if (!newStart && !endDate) {
                    onChange(field.field_key, null)
                  } else if (endDate) {
                    onChange(field.field_key, newStart ? `${newStart} s/d ${endDate}` : endDate)
                  } else {
                    onChange(field.field_key, newStart || null)
                  }
                }}
                className={base}
                disabled={disabled}
                required={field.wajib && !endDate}
              />
            </div>
            <div>
              <label className="text-[10px] text-gray-400 font-medium block mb-0.5">Sampai (Opsional)</label>
              <input
                id={`${idPrefix}field-${field.field_key}-end`}
                type="date"
                value={endDate ? String(endDate).split('T')[0] : ''}
                onChange={(e) => {
                  const newEnd = e.target.value
                  if (!newEnd) {
                    onChange(field.field_key, startDate || null)
                  } else {
                    onChange(field.field_key, startDate ? `${startDate} s/d ${newEnd}` : newEnd)
                  }
                }}
                className={base}
                disabled={disabled}
                min={startDate ? String(startDate).split('T')[0] : undefined}
              />
            </div>
          </div>
          {isRange && (
            <p className="text-[11px] text-blue-600 dark:text-blue-400 font-medium">
              Rentang aktif: {value}
            </p>
          )}
        </div>
      )
    }

    case 'pilihan': {
      // Opsi bersyarat: kolom pilihan lain yang opsinya berbeda tergantung nilai kolom "depends_on" di baris yang sama
      // (mis. "Jenjang Jabatan" opsinya beda untuk Instruktur vs Widyaiswara). Dikonfigurasi lewat field.opsi_bersyarat.
      // field.opsiLabel (opsional): teks tampilan per nilai, mis. { ABAC: 'ABAC — Tenaga Kepelatihan' }
      let opsi = field.opsi_pilihan || []
      let waitingOn = null
      if (field.opsi_bersyarat?.depends_on) {
        const driverKey = field.opsi_bersyarat.depends_on
        const driverVal = allValues?.[driverKey]
        if (!driverVal) {
          opsi = []
          waitingOn = allFields?.find(f => f.field_key === driverKey)?.label || 'kolom sebelumnya'
        } else {
          opsi = field.opsi_bersyarat.options?.[driverVal] || []
        }
      }
      return (
        <select
          id={`${idPrefix}field-${field.field_key}`}
          value={value ?? ''}
          onChange={(e) => onChange(field.field_key, e.target.value || null)}
          className={`${base} form-select`}
          disabled={disabled || !!waitingOn}
          required={field.wajib}
        >
          <option value="">{waitingOn ? `- Pilih ${waitingOn} dulu -` : '- Pilih -'}</option>
          {opsi.map(opt => (
            <option key={opt} value={opt}>{field.opsiLabel?.[opt] || opt}</option>
          ))}
        </select>
      )
    }

    case 'teks_panjang':
      return (
        <textarea
          id={`${idPrefix}field-${field.field_key}`}
          value={value ?? ''}
          onChange={(e) => onChange(field.field_key, e.target.value || null)}
          className={`${base} resize-y`}
          rows={3}
          disabled={disabled}
          required={field.wajib}
          placeholder={field.label}
        />
      )

    case 'teks':
    default:
      if (field.field_key === 'alamat' || field.field_key === 'progress_pelaksanaan' || field.field_key === 'permasalahan') {
        return (
          <textarea
            id={`${idPrefix}field-${field.field_key}`}
            value={value ?? ''}
            onChange={(e) => onChange(field.field_key, e.target.value || null)}
            className={`${base} resize-y`}
            rows={2}
            disabled={disabled}
            required={field.wajib}
            placeholder={field.label}
          />
        )
      }
      return (
        <>
          <input
            id={`${idPrefix}field-${field.field_key}`}
            type="text"
            value={value ?? ''}
            onChange={(e) => onChange(field.field_key, e.target.value || null)}
            className={base}
            disabled={disabled}
            required={field.wajib}
            placeholder={field.label}
            list={field.saran?.length ? `${idPrefix}saran-${field.field_key}` : undefined}
            autoComplete={field.saran?.length ? 'off' : undefined}
          />
          {/* field.saran (opsional): pilihan isian yang sudah pernah dipakai, mis. Kode RO di minggu yang sama */}
          {field.saran?.length > 0 && (
            <datalist id={`${idPrefix}saran-${field.field_key}`}>
              {field.saran.map(s => <option key={s} value={s} />)}
            </datalist>
          )}
        </>
      )
  }
}

/**
 * DynamicFormRekap — untuk level Minggu (pengisian form mingguan)
 */
export function DynamicFormRekap({ fields, values, onChange, disabled, onSubmit, loading, bare = false, idPrefix = '', jenisDataId, uptKey }) {
  const activeFields = fields.filter(f => f.aktif).sort((a, b) => a.urutan - b.urutan)
  // bare: hanya kolom-kolomnya (dipakai saat satu <form> memuat beberapa baris/pelatihan)
  const Wrapper = bare ? 'div' : 'form'
  // Saat kolom "penentu" (depends_on) berubah, kosongkan kolom yang opsinya bergantung padanya (opsi lama bisa tidak
  // relevan lagi untuk nilai baru — mis. ganti dari Instruktur ke Widyaiswara, Jenjang Jabatan harus dipilih ulang).
  const handleChange = (key, val) => {
    onChange(key, val)
    activeFields.filter(f => f.opsi_bersyarat?.depends_on === key).forEach(f => onChange(f.field_key, null))
  }

  return (
    <Wrapper onSubmit={bare ? undefined : onSubmit} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {activeFields.map(field => {
          const isFullWidth = field.tipe === 'teks_panjang' || field.tipe === 'file' || field.field_key.includes('laporan') || field.field_key === 'progress_pelaksanaan' || field.field_key === 'permasalahan' || field.field_key === 'nama_pelatihan' || field.field_key === 'judul_kegiatan'
          return (
            <div key={field.id || field.field_key} className={isFullWidth ? 'sm:col-span-2' : ''}>
              <label className="form-label" htmlFor={`${idPrefix}field-${field.field_key}`}>
                {field.label}
                {field.wajib && <span className="text-rose-500 ml-1">*</span>}
                {/* field.kunci: isian dari tingkat induk (mis. KRO saat menambah RO), hanya dilihat */}
                {field.kunci && <Lock size={11} className="inline ml-1.5 -mt-0.5 text-gray-400" aria-label="Terkunci" />}
              </label>
              <FieldInput
                field={field}
                value={values[field.field_key]}
                onChange={handleChange}
                disabled={disabled || !!field.kunci}
                idPrefix={idPrefix}
                jenisDataId={jenisDataId}
                uptKey={uptKey}
                allValues={values}
                allFields={activeFields}
              />
            </div>
          )
        })}
      </div>

      {!disabled && !bare && (
        <div className="pt-3 border-t border-gray-100 dark:border-gray-800">
          <button type="submit" className="btn-primary w-full" disabled={loading}>
            {loading ? 'Menyimpan...' : 'Simpan'}
          </button>
        </div>
      )}
    </Wrapper>
  )
}

/**
 * DynamicFormEntry — untuk level Bulan (satu baris data per-orang)
 */
export function DynamicFormEntry({ fields, values, onChange, disabled, onSubmit, loading, idPrefix = '', jenisDataId, uptKey }) {
  const activeFields = fields.filter(f => f.aktif).sort((a, b) => a.urutan - b.urutan)
  const handleChange = (key, val) => {
    onChange(key, val)
    activeFields.filter(f => f.opsi_bersyarat?.depends_on === key).forEach(f => onChange(f.field_key, null))
  }

  return (
    <form onSubmit={onSubmit} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[70vh] overflow-y-auto pr-1">
        {activeFields.map(field => {
          const isFullWidth = field.tipe === 'file' || field.field_key === 'alamat' || field.field_key === 'link_sertifikat_pelatihan_by_name' || field.field_key === 'nama_pelatihan'
          return (
            <div key={field.id || field.field_key} className={isFullWidth ? 'sm:col-span-2' : ''}>
              <label className="form-label" htmlFor={`${idPrefix}field-${field.field_key}`}>
                {field.label}
                {field.wajib && <span className="text-rose-500 ml-1">*</span>}
                {field.is_identitas && (
                  <span className="ml-1 text-amber-500 text-xs font-normal" title="Kolom Identitas Pribadi">🔒 Identitas</span>
                )}
              </label>
              <FieldInput
                field={field}
                value={values[field.field_key]}
                onChange={handleChange}
                disabled={disabled}
                jenisDataId={jenisDataId}
                uptKey={uptKey}
                allValues={values}
                allFields={activeFields}
              />
            </div>
          )
        })}
      </div>

      {!disabled && (
        <div className="pt-2 border-t border-gray-100 dark:border-gray-800">
          <button type="submit" className="btn-primary w-full" disabled={loading}>
            {loading ? 'Menyimpan...' : 'Simpan Data Baris'}
          </button>
        </div>
      )}
    </form>
  )
}

// Default export — auto-pilih berdasarkan level
export default function DynamicForm({ level, ...props }) {
  if (level === 'bulan') return <DynamicFormEntry {...props} />
  return <DynamicFormRekap {...props} />
}
